55	// Converts the TensorFlow graph into an XLA computation, by executing the
56	// graph symbolically, with each op building up the XLA HLO.
57	absl::Status ConvertGraphToXla(std::unique_ptr<Graph> graph,
58	                               const tf2xla::Config& config,
59	                               xla::Client* client,
60	                               xla::XlaComputation* computation) {
61	  XlaOpRegistry::RegisterCompilationKernels();
62	  for (Node* node : graph->nodes()) {
63	    node->set_assigned_device_name(
64	        absl::StrCat("/device:", DEVICE_CPU_XLA_JIT));
65	  }
66	  std::vector<XlaCompiler::Argument> xla_args;
67	  TF_RETURN_IF_ERROR(CreateXlaArgs(*graph, &xla_args));
68	
69	  PopulateXlaArgs(config, &xla_args);
70	  // Compile the graph into an XLA computation.
71	  XlaCompiler::Options compiler_options;
72	  compiler_options.client = client;
73	  compiler_options.device_type = DeviceType(DEVICE_CPU_XLA_JIT);
74	  compiler_options.flib_def = &graph->flib_def();
75	  compiler_options.graph_def_version = graph->versions().producer();
76	  compiler_options.allow_cpu_custom_calls = true;
77	
78	  XlaCompiler compiler(compiler_options);
79	
80	  XlaCompiler::CompilationResult result;
81	
82	  XlaCompiler::CompileOptions options;
83	  options.alias_resource_update = true;
84	  TF_RETURN_IF_ERROR(compiler.CompileGraph(
85	      options, "tfcompile", std::move(graph), xla_args, &result));
86	  *computation = std::move(*result.computation);
87	
88	  int num_const_results = 0;
89	  for (int i = 0, end = result.outputs.size(); i < end; ++i) {
90	    // Ending up with const results (i.e. output args) is an error, since it
91	    // means that one or more fetches that the user specified will be dropped
92	    // from the generated function.  It's most likely a configuration error,
93	    // since the user shouldn't be asking for output args that end up as consts.
94	    //
95	    // TODO(toddw): Provide a way for the user to access const output args,
96	    // e.g. perhaps hard-coded into the header, or somehow copied into the
97	    // output buffers.
98	    if (result.outputs[i].is_constant) {
99	      ++num_const_results;
100	      LOG(ERROR) << "ConstRetVal index:" << i
101	                 << " value:" << result.outputs[i].constant_value.DebugString();
102	    }
103	  }
104	  if (num_const_results > 0) {
105	    return absl::UnimplementedError(
106	        absl::StrCat("Conversion from TensorFlow graph to XLA resulted in ",
107	                     num_const_results,
108	                     " constant results.  The configuration of "
109	                     "the output args (i.e. fetch ids) is probably wrong."));
110	  }
111	  {
112	    // Verify that the readonly bits on variables are set correctly by the user.
113	    std::vector<bool> updated_inputs(xla_args.size());
114	    for (const XlaCompiler::ResourceUpdate& update : result.resource_updates) {
115	      updated_inputs[update.input_index] = true;
116	    }
117	    int64_t input_index = xla_args.size() - config.variable_size();
118	    for (const tf2xla::Variable& variable : config.variable()) {
119	      if (variable.readonly() == updated_inputs[input_index]) {
120	        return absl::InvalidArgumentError(absl::StrCat(
121	            "Variable \"", variable.node_name(), "\" is marked as ",
122	            variable.readonly() ? "" : "not ", "readonly, but is ",
123	            updated_inputs[input_index] ? "" : "not ",
124	            "modified by the computation."));
125	      }
126	      ++input_index;
127	    }
128	  }
129	  return absl::OkStatus();
130	}
