132	absl::Status ConvertVarHandlesToAotVarHandles(GraphDef* graph_def) {
133	  auto update_var_handle_op_node = [](NodeDef& node) -> absl::Status {
134	    if (node.op() == "VarHandleOp") {
135	      node.set_op(tfcompile::kXlaAotOnlyVarHandleOp);
136	      const auto& it = node.attr().find("allowed_devices");
137	      if (it != node.attr().end()) {
138	        if (!it->second.list().s().empty()) {
139	          return absl::InvalidArgumentError(
140	              "VarHandleOp with non-empty allowed devices is not supported.");
141	        }
142	        node.mutable_attr()->erase("allowed_devices");
143	      }
144	    }
145	    return absl::OkStatus();
146	  };
147	  for (auto& node : *graph_def->mutable_node()) {
148	    TF_RETURN_IF_ERROR(update_var_handle_op_node(node));
149	  }
150	  for (auto& fn : *graph_def->mutable_library()->mutable_function()) {
151	    for (auto& node : *fn.mutable_node_def()) {
152	      TF_RETURN_IF_ERROR(update_var_handle_op_node(node));
153	    }
154	  }
155	  return absl::OkStatus();
156	}
