48	class TFToMhloPass
49	    : public mlir::PassWrapper<TFToMhloPass,
50	                               mlir::OperationPass<mlir::func::FuncOp>> {
51	 public:
52	  explicit TFToMhloPass(bool skip_quantization_ops = false,
53	                        bool skip_resize = false,
54	                        bool skip_partitioned_calls = false)
55	      : PassWrapper() {
56	    skip_quantization_ops_ = skip_quantization_ops;
57	    skip_resize_ = skip_resize;
