68	  void runOnOperation() override;
69	
70	  void getDependentDialects(DialectRegistry &registry) const override {
71	    mlir::mhlo::registerAllMhloDialects(registry);
72	    mlir::stablehlo::registerAllDialects(registry);
73	    registry.insert<mlir::func::FuncDialect, mlir::arith::ArithDialect>();
74	    registry.insert<shape::ShapeDialect>();
75	  }
