98	void TFToMhloPass::runOnOperation() {
99	  auto func = getOperation();
100	  MLIRContext *context = func->getContext();
101	
102	  RewritePatternSet patterns(context);
103	  odml::PopulateLegalizeTfPatterns(context, &patterns);
104	  TF::PopulateTFLoweringBeforeHLOPatterns(context, &patterns);
105	  mhlo::Tf2XlaTypeConverter converter;
106	  mhlo::PopulateLegalizeTfWithTf2XlaPatterns(
107	      "XLA_CPU_JIT", patterns, context, converter, /*prefer_tf2xla=*/false);
108	  stablehlo::StablehloToHloTypeConverter hlo_converter;
109	  chlo::populateChloToHloPatterns(context, &hlo_converter, &patterns);
110	  chlo::ConstantLikeOp::getCanonicalizationPatterns(patterns, context);
111	
112	  ConversionTarget target(*context);
113	  target.addIllegalDialect<chlo::ChloDialect>();
114	  target.addLegalDialect<mhlo::MhloDialect>();
115	  target.addLegalDialect<arith::ArithDialect>();
116	  target.addLegalDialect<func::FuncDialect>();
117	  target.addLegalDialect<tensor::TensorDialect>();
118	  target.addLegalDialect<shape::ShapeDialect>();
119	  target.addLegalOp<func::CallOp>();
120	
121	  if (skip_quantization_ops_) {
122	    target.addLegalOp<TF::FakeQuantWithMinMaxVarsOp>();
123	    target.addLegalOp<TF::FakeQuantWithMinMaxVarsPerChannelOp>();
124	    target.addLegalOp<TF::FakeQuantWithMinMaxArgsOp>();
125	    target.addLegalOp<TF::QuantizeAndDequantizeV2Op>();
126	    target.addLegalOp<TF::QuantizeAndDequantizeV3Op>();
127	  }
128	  if (skip_resize_) {
129	    target.addLegalOp<TF::ResizeBilinearOp>();
130	    target.addLegalOp<TF::ResizeNearestNeighborOp>();
131	  }
132	  if (skip_partitioned_calls_) {
133	    target.addLegalOp<TF::PartitionedCallOp>();
134	    target.addLegalOp<TF::StatefulPartitionedCallOp>();
135	  }
136	
137	  FrozenRewritePatternSet frozen_patterns(std::move(patterns));
138	  if (failed(applyPartialConversion(func, target, frozen_patterns))) {
139	    return signalPassFailure();
140	  }
141	}
